document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("roas-form");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("adSpend").value),t=parseFloat(document.getElementById("revenue").value);if(0===n)return document.getElementById("roas-result").innerHTML="<p style='color:red;'>Advertising spend cannot be zero.</p>",void 0;const i=t/n,r=(100*i).toFixed(0),o=e=>e.toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:0,maximumFractionDigits:0});let d="",a="",s="";i>=5?(d="Excellent",a="Scale this campaign! Increase budget allocation.",s="#28a745"):i>=4?(d="Very Good",a="Strong performance. Consider scaling with monitoring.",s="#20c997"):i>=3?(d="Good",a="Solid performance. Optimize targeting and creative.",s="#ffc107"):i>=2?(d="Fair",a="Needs improvement. Review strategy and optimize.",s="#fd7e14"):i>=1?(d="Poor",a="Campaign is barely profitable. Major optimization needed.",s="#dc3545"):(d="Losing Money",a="Campaign is unprofitable. Pause and restructure immediately.",s="#dc3545"),document.getElementById("roas-result").innerHTML=`\n      <h3>ROAS Analysis Results:</h3>\n      <div style="background: #f8f9fa; padding: 1.5rem; border-radius: 8px; border-left: 4px solid ${s};">\n        <div style="margin-bottom: 1rem;">\n          <p style="font-size: 1.2em; margin: 0;"><strong>ROAS: ${i.toFixed(2)}:1</strong> (${r}% return)</p>\n          <p style="color: ${s}; font-weight: bold; margin: 0.5rem 0;"><strong>Performance: ${d}</strong></p>\n        </div>\n        \n        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; margin: 1rem 0;">\n          <div>\n            <p style="margin: 0; font-size: 0.9em; color: #666;">Ad Spend</p>\n            <p style="margin: 0; font-weight: bold;">${o(n)}</p>\n          </div>\n          <div>\n            <p style="margin: 0; font-size: 0.9em; color: #666;">Revenue Generated</p>\n            <p style="margin: 0; font-weight: bold;">${o(t)}</p>\n          </div>\n        </div>\n        \n        <div style="margin-top: 1rem; padding-top: 1rem; border-top: 1px solid #dee2e6;">\n          <p style="margin: 0; font-style: italic;"><strong>Recommendation:</strong> ${a}</p>\n        </div>\n      </div>\n    `})});